package com.coraline.feast;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.*;
import net.minecraft.world.item.*;
import net.minecraft.world.entity.projectile.Snowball;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.gametest.*;

@GameTestHolder("coraline") @PrefixGameTestTemplate(false)
public final class MallBattleGameTests {
    @GameTest(template="empty") public static void snowHelperCannotThrowOrDamage(GameTestHelper h){var f=ExpeditionGameTests.fixture(h,OtherMotherActivities.Activity.SNOWBALL_BATTLE);var n=f.s().loop.expedition;n.putInt("Phase",2);n.putInt("Health",5);var helper=net.minecraftforge.common.util.FakePlayerFactory.get(f.p().serverLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"SnowHelper"));helper.getPersistentData().putUUID("CoralineVisitDoor",f.s().door);helper.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(com.coraline.registry.ModItems.SNOWBALL_POUCH.get()));SnowballBattleActivity.throwBall(helper);h.assertTrue(!n.contains("NextThrow"),"Helper fired an owner's snowball");SnowballBattleActivity.hit(f.p(),f.s(),helper,f.p());h.assertTrue(n.getInt("Health")==5,"Helper changed owner health");h.succeed();}
    @GameTest(template="empty") public static void mallStockStableVariedGated(GameTestHelper h){var signatures=new HashSet<String>();for(int i=0;i<100;i++){var stock=MallStock.generate(i,false,false);h.assertTrue(stock.equals(MallStock.generate(i,false,false)),"Reopening rerolls stock");int cost=0;var stores=new HashSet<Integer>();for(var tag:stock){var n=(CompoundTag)tag;stores.add(n.getInt("Store"));cost+=n.getInt("Price");var stack=ItemStack.of(n.getCompound("Item"));h.assertTrue(!stack.isEmpty(),"Invalid product");String id=net.minecraftforge.registries.ForgeRegistries.ITEMS.getKey(stack.getItem()).toString();h.assertTrue((!id.contains("perfect_")||id.endsWith("perfect_roast_dinner"))&&!id.contains("soul_")&&!id.contains("button_key")&&!id.contains("moving_truck")&&!id.contains("moonstone")&&!id.contains("other_diamond"),"Progression bypass: "+id);}h.assertTrue(cost>4000&&stores.size()==MallStock.STORES.length,"Budget buys everything or stores missing");signatures.add(stock.toString());}h.assertTrue(signatures.size()>90,"No rotating stock");h.succeed();}
    @GameTest(template="empty") public static void mallBudgetOwnershipAndSoldOut(GameTestHelper h){var f=ExpeditionGameTests.fixture(h,OtherMotherActivities.Activity.SHOPPING_MALL);var n=f.s().loop.expedition;n.putInt("Phase",1);n.putInt("Balance",1000);n.put("Stock",MallStock.generate(17,true,true));h.assertTrue(!ShoppingMallActivity.purchase(f.s(),UUID.randomUUID(),0),"Helper spent owner budget");var list=n.getList("Stock",10);int premium=-1;for(int i=0;i<list.size();i++)if(list.getCompound(i).getInt("Price")==950)premium=i;h.assertTrue(premium>=0,"Luxury choice missing");h.assertTrue(ShoppingMallActivity.purchase(f.s(),f.p().getUUID(),premium),"Valid premium purchase failed");h.assertTrue(n.getInt("Balance")==50,"Wrong price deducted");h.assertTrue(!ShoppingMallActivity.purchase(f.s(),f.p().getUUID(),premium),"Duplicate premium");for(int i=0;i<list.size();i++)for(int j=0;j<4;j++)ShoppingMallActivity.purchase(f.s(),f.p().getUUID(),i);h.assertTrue(n.getInt("Balance")>=0,"Negative currency");var saved=OtherMotherLoopState.load(f.s().loop.save());h.assertTrue(saved.expedition.equals(n),"Shopping bag lost on save");h.succeed();}
    @GameTest(template="empty") public static void mallConfirmationAndNonce(GameTestHelper h){var f=ExpeditionGameTests.fixture(h,OtherMotherActivities.Activity.SHOPPING_MALL);var n=f.s().loop.expedition;n.putInt("Phase",1);n.putInt("Balance",1000);n.put("Stock",MallStock.generate(9,true,true));var list=n.getList("Stock",10);int i=0;while(list.getCompound(i).getInt("Price")!=950)i++;var entry=list.getCompound(i);f.p().setPos(Vec3.atCenterOf(MallScenery.shop(f.c(),entry.getInt("Store"))));ShoppingMallActivity.open(f.p(),f.s(),i);var nonce=n.getUUID("MenuNonce");ShoppingMallActivity.request(f.p(),nonce,i,1);h.assertTrue(n.getInt("Balance")==1000&&n.getInt("Confirm")==i,"First expensive click spent tokens");ShoppingMallActivity.request(f.p(),nonce,i,1);h.assertTrue(n.getInt("Balance")==50,"Confirmation failed");ShoppingMallActivity.request(f.p(),nonce,i,1);h.assertTrue(n.getInt("Balance")==50,"Replayed packet spent tokens");h.succeed();}
    @GameTest(template="empty") public static void mallPayoutOnceOverflow(GameTestHelper h){var f=ExpeditionGameTests.fixture(h,OtherMotherActivities.Activity.SHOPPING_MALL);var n=f.s().loop.expedition;n.putInt("Phase",1);n.putInt("Balance",1000);n.put("Stock",MallStock.generate(9,false,false));h.assertTrue(ShoppingMallActivity.purchase(f.s(),f.p().getUUID(),0),"Purchase rejected");for(int i=0;i<36;i++)f.p().getInventory().setItem(i,new ItemStack(Items.COBBLESTONE,64));ShoppingMallActivity.settle(f.p(),f.s());ShoppingMallActivity.settle(f.p(),f.s());h.assertTrue(n.getInt("Balance")==0&&n.getList("ShoppingBag",10).isEmpty(),"Currency/bag persisted after checkout");h.assertTrue(f.p().getPersistentData().getList("CoralineMallDelivery",10).size()==1,"Pending delivery missing");LoopProps.hold(f.p().serverLevel(),f.p().blockPosition());h.runAfterDelay(10,()->{ShoppingMallActivity.deliver(f.p());ShoppingMallActivity.deliver(f.p());h.runAfterDelay(1,()->{var drops=f.p().serverLevel().getEntitiesOfClass(ItemEntity.class,f.p().getBoundingBox().inflate(4),e->e.getPersistentData().hasUUID("CoralineAwardOwner")&&e.getPersistentData().getUUID("CoralineAwardOwner").equals(f.p().getUUID()));h.assertTrue(drops.size()==1&&drops.get(0).getItem().getCount()==6,"Overflow lost or duplicated: "+drops.stream().map(e->e.getItem().toString()).toList());h.succeed();});});}
    @GameTest(template="empty",timeoutTicks=600) public static void mallAccessibleDisplaysAndStairs(GameTestHelper h){var f=ExpeditionGameTests.fixture(h,OtherMotherActivities.Activity.SHOPPING_MALL);ShoppingMallActivity.build(f.p(),f.s(),f.p().serverLevel(),f.c());for(int store=0;store<MallStock.STORES.length;store++){var b=MallScenery.shop(f.c(),store);var door=b.offset(-MallScenery.side(store)*12,0,0);h.assertTrue(f.p().level().isEmptyBlock(door)&&f.p().level().isEmptyBlock(door.above()),"Blocked shop entrance");for(int slot=0;slot<MallStock.ITEMS_PER_VISIT;slot++)h.assertTrue(f.p().level().isEmptyBlock(MallScenery.display(f.c(),store,slot).above()),"Product obscured");}h.assertTrue(f.p().level().isEmptyBlock(f.c().offset(0,8,-82)),"Blocked upper landing");h.succeed();}
    @GameTest(template="empty",timeoutTicks=600) public static void snowCountdownCooldownHealthAndLoss(GameTestHelper h){var f=ExpeditionGameTests.fixture(h,OtherMotherActivities.Activity.SNOWBALL_BATTLE);var p=f.p();var s=f.s();SnowballBattleActivity.build(p,s,p.serverLevel(),f.c());SnowballBattleActivity.begin(p,s);float hearts=p.getHealth();SnowballBattleActivity.throwBall(p);h.assertTrue(!s.loop.expedition.contains("NextThrow"),"Throw during countdown");s.loop.expedition.putInt("Phase",2);SnowballBattleActivity.throwBall(p);long next=s.loop.expedition.getLong("NextThrow");SnowballBattleActivity.throwBall(p);h.assertTrue(next==s.loop.expedition.getLong("NextThrow"),"Cooldown bypass");for(int i=0;i<5;i++)SnowballBattleActivity.hit(p,s,p,null);h.assertTrue(s.loop.expedition.getInt("Health")==0&&s.loop.expedition.getInt("Phase")==5&&ActivityWorld.exitReady(s),"Loss did not end safely");h.assertTrue(p.getHealth()==hearts&&p.isAlive(),"Activity changed real health");h.assertTrue(!p.getInventory().contains(new ItemStack(com.coraline.registry.ModItems.SNOWBALL_POUCH.get())),"Pouch retained");h.succeed();}
    @GameTest(template="empty",timeoutTicks=600) public static void snowLastSurvivorPrizeOnce(GameTestHelper h){var f=ExpeditionGameTests.fixture(h,OtherMotherActivities.Activity.SNOWBALL_BATTLE);var p=f.p();var s=f.s();SnowballBattleActivity.build(p,s,p.serverLevel(),f.c());SnowballBattleActivity.begin(p,s);s.loop.expedition.putInt("Phase",2);s.loop.expedition.putLong("BattleAt",OtherMotherLoop.now(p));var alive=SnowballBattleActivity.living(p,s);h.assertTrue(alive.size()==7,"Wrong fighter count");for(var npc:alive)if(npc!=p)for(int i=0;i<5;i++)SnowballBattleActivity.hit(p,s,npc,p);SnowballBattleActivity.tick(p,s,f.c());h.assertTrue(s.loop.expedition.getInt("Phase")==3,"Last survivor not winner");var prize=p.serverLevel().getEntitiesOfClass(ScenePropEntity.class,ExpeditionActivities.bounds(f.c(),s.loop.activity),e->e.slot==760).get(0);SnowballBattleActivity.interactProp(p,s,prize);int count=p.getInventory().countItem(Items.ENCHANTED_GOLDEN_APPLE);SnowballBattleActivity.interactProp(p,s,prize);h.assertTrue(count==1&&p.getInventory().countItem(Items.ENCHANTED_GOLDEN_APPLE)==1&&ActivityWorld.exitReady(s),"Prize duplicated or exit missing");h.succeed();}
}
